import { expect, it } from 'vitest'
import { calculate, calculate6, parseIp6, type SubnetInfo } from '../src/subnet'

// IPv4 cases have a numeric ip, IPv6 ones a string (and no broadcast)
type Case = Omit<SubnetInfo, 'prefix' | 'broadcast'> & { ip: number | string; prefix: number; broadcast?: string }

// cases.json is generated by scripts/gen_cases.py (npm pretest) and not committed
const cases = Object.values(import.meta.glob<Case[]>('./cases.json', { eager: true, import: 'default' }))[0]

it('matches Python ipaddress on generated cases', () => {
  expect(cases, 'cases.json missing, run: python3 scripts/gen_cases.py').toBeDefined()
  for (const { ip, ...expected } of cases ?? [])
    expect(
      typeof ip === 'number' ? calculate(ip, expected.prefix) : calculate6(parseIp6(ip) ?? [], expected.prefix),
    ).toEqual(expected)
})
